app.get("/selection/production/total", async (req, res) => {
  try {
    const sql2 = `
      select u.UrunBirimID, sum(u.Miktar) as Miktar, (select t.FirmaAdi from TedarikciTB t where t.ID = u.TedarikciID) as TedarikciAdi, u.TedarikciID 
      from UretimTB u 
      where YEAR(u.Tarih) = YEAR(GETDATE()) and MONTH(u.Tarih) = MONTH(GETDATE()) 
      group by u.TedarikciID, u.UrunBirimID
    `;
    const sql22 = `
      select sum(u.Miktar) as Miktar, (select t.FirmaAdi from TedarikciTB t where t.ID = u.TedarikciID) as TedarikciAdi, u.TedarikciID, u.UrunBirimID 
      from UretimTB u 
      where u.UrunBirimID = 1 and YEAR(u.Tarih) = YEAR(GETDATE()) 
      group by u.TedarikciID, u.UrunBirimID
    `;
    const sql3 = `
      select su.TedarikciID, YEAR(se.Tarih) as Year, MONTH(se.Tarih) as Month, se.Tarih, se.SiparisNo, su.Miktar, su.UrunBirimID, (select ub.BirimAdi from UrunBirimTB ub where ub.ID = su.UrunBirimID)as BirimAdi 
      from SiparisEkstraGiderlerTB se 
      inner join SiparisUrunTB su on su.SiparisNo=se.SiparisNo
      where YEAR(se.Tarih) = YEAR(GETDATE()) and MONTH(se.Tarih) = MONTH(GETDATE())
    `;
    const sql4 = `
      select su.TedarikciID, YEAR(se.Tarih) as Year, MONTH(se.Tarih) as Month, se.Tarih, se.SiparisNo, su.Miktar, su.UrunBirimID, (select ub.BirimAdi from UrunBirimTB ub where ub.ID = su.UrunBirimID)as BirimAdi 
      from SiparisEkstraGiderlerTB se 
      inner join SiparisUrunTB su on su.SiparisNo=se.SiparisNo
      where YEAR(se.Tarih) = YEAR(GETDATE()) 
    `;
    const [
      productMonth,
      productYear,
      productSelectionMonth,
      productSelectionYear
    ] = await Promise.all([
      mssql.query(sql2),
      mssql.query(sql22),
      mssql.query(sql3),
      mssql.query(sql4)
    ]);
    let data = {
      mekmerMonthSqm: 0,
      mekmerMonthPcs: 0,
      mekmerMonthMt: 0,
      mekmozMonthSqm: 0,
      mekmozMonthPcs: 0,
      mekmozMonthMt: 0,
      disMonthSqm: 0,
      disMonthPcs: 0,
      disMonthMt: 0,
      mekmerYearSqm: 0,
      mekmerYearPcs: 0,
      mekmerYearMt: 0,
      mekmozYearSqm: 0,
      mekmozYearPcs: 0,
      mekmozYearMt: 0,
      disYearSqm: 0,
      disYearPcs: 0,
      disYearMt: 0,
      monthTotalSqm: 0,
      monthTotalPcs: 0,
      monthTotalMt: 0,
      yearTotalSqm: 0,
      yearTotalPcs: 0,
      yearTotalMt: 0
    };
    const processData = (record, isMonth) => {
      if (record.UrunBirimID == 1)
        isMonth ? data.monthTotalSqm += record.Miktar : data.yearTotalSqm += record.Miktar;
      else if (record.UrunBirimID == 2)
        isMonth ? data.monthTotalPcs += record.Miktar : data.yearTotalPcs += record.Miktar;
      else if (record.UrunBirimID == 3)
        isMonth ? data.monthTotalMt += record.Miktar : data.yearTotalMt += record.Miktar;
      if (record.TedarikciID == 1) {
        if (record.UrunBirimID == 1)
          isMonth ? data.mekmerMonthSqm += record.Miktar : data.mekmerYearSqm += record.Miktar;
        else if (record.UrunBirimID == 2)
          isMonth ? data.mekmerMonthPcs += record.Miktar : data.mekmerYearPcs += record.Miktar;
        else if (record.UrunBirimID == 3)
          isMonth ? data.mekmerMonthMt += record.Miktar : data.mekmerYearMt += record.Miktar;
      } else if (record.TedarikciID == 123) {
        if (record.UrunBirimID == 1)
          isMonth ? data.mekmozMonthSqm += record.Miktar : data.mekmozYearSqm += record.Miktar;
        else if (record.UrunBirimID == 2)
          isMonth ? data.mekmozMonthPcs += record.Miktar : data.mekmozYearPcs += record.Miktar;
        else if (record.UrunBirimID == 3)
          isMonth ? data.mekmozMonthMt += record.Miktar : data.mekmozYearMt += record.Miktar;
      } else {
        if (record.UrunBirimID == 1)
          isMonth ? data.disMonthSqm += record.Miktar : data.disYearSqm += record.Miktar;
        else if (record.UrunBirimID == 2)
          isMonth ? data.disMonthPcs += record.Miktar : data.disYearPcs += record.Miktar;
        else if (record.UrunBirimID == 3)
          isMonth ? data.disMonthMt += record.Miktar : data.disYearMt += record.Miktar;
      }
    };
    productMonth.recordset.forEach((x) => processData(x, true));
    productSelectionMonth.recordset.forEach((x) => processData(x, true));
    productYear.recordset.forEach((x) => processData(x, false));
    productSelectionYear.recordset.forEach((x) => processData(x, false));
    res.status(200).json({ data });
  } catch (error) {
    console.error("\xDCretim Total API Hatas\u0131:", error);
    res.status(500).json({ status: false, message: "Veriler y\xFCklenirken hata olu\u015Ftu." });
  }
});
