app.put("/card/update", (req, res) => {
  sizeIdControl(
    req.body.En,
    req.body.Boy,
    req.body.Kenar,
    req.body.OlcuId
  ).then((sizeId2) => {
    if (sizeId2) {
      productIdControl(req.body.UrunAdi, req.body.UrunId).then((productId2) => {
        if (productId2) {
          categoryIdControl(req.body.KategoriAdi, req.body.KategoriId).then(
            (categoryId2) => {
              if (categoryId2) {
                surfaceIdControl(req.body.YuzeyIslemAdi, req.body.YuzeyId).then(
                  (surfaceId2) => {
                    const cardRequest = new mssql.Request();
                    cardRequest.input("UrunID", mssql.Int, productId2);
                    cardRequest.input("YuzeyID", mssql.Int, surfaceId2);
                    cardRequest.input("OlcuID", mssql.Int, sizeId2);
                    cardRequest.input("KategoriID", mssql.Int, categoryId2);
                    cardRequest.input("ID", mssql.Int, req.body.ID);
                    cardRequest.query(
                      "update UrunKartTB SET UrunID=@UrunID, YuzeyID=@YuzeyID,OlcuID=@OlcuID,KategoriID=@KategoriID where ID=@ID"
                    ).then((updateCard) => {
                      if (updateCard.rowsAffected[0] == 1) {
                        res.status(200).json({ status: true });
                      } else {
                        res.status(200).json({ status: false });
                      }
                    }).catch(() => res.status(500).json({ status: false }));
                  }
                );
              }
            }
          );
        }
      });
    }
  });
});
