function __stringCharacterChange(event) {
  if (event == null || event == void 0) {
    return "";
  } else {
    const data = event.split("'");
    let value2 = "";
    if (data.length > 0) {
      data.forEach((x) => {
        value2 += x + "''";
      });
      const value22 = value2.substring(0, value2.length - 2);
      return value22;
    } else {
      return event;
    }
  }
}
