app.get("/offer/shared/list", (req, res) => {
  const categorySql = `
                    select 

                ytk.Id,
                ytk.KategoriAdi

            from YeniTeklif_KategorilerTB ytk
    `;
  const productSql = `
        select 
	ytu.Id,
	ytu.UrunAdi
from YeniTeklif_UrunlerTB ytu
    `;
  const sizeSql = `
        select 
	ytoe.id,
	ytoe.EnBoy
from YeniTeklif_Olcu_EnBoyTB ytoe
    `;
  const thicknessSql = `
                select 
            ytok.id,
            ytok.Kalinlik
        from YeniTeklif_Olcu_KalinlikTB ytok
    `;
  const surfaceSql = `
        select 

	yty.Id,
	yty.IslemAdi

from YeniTeklif_YuzeyIslemTB yty
    `;
  const unitSql = `
        select

            ytu.Birim

        from YeniTeklif_UrunKayitTB ytu
        where ytu.Birim is not null and ytu.Birim != '' and ytu.Birim not in ('Carrara White','Bianco Ibiza')
        group by ytu.Birim
    `;
  mssql.query(categorySql, (err, category) => {
    mssql.query(productSql, (err2, product) => {
      mssql.query(sizeSql, (err3, size) => {
        mssql.query(thicknessSql, (err4, thickness) => {
          mssql.query(surfaceSql, (err5, surface) => {
            mssql.query(unitSql, (err6, unit) => {
              res.status(200).json({
                category: category.recordset,
                product: product.recordset,
                size: size.recordset,
                thickness: thickness.recordset,
                unit: unit.recordset,
                surface: surface.recordset
              });
            });
          });
        });
      });
    });
  });
});
