function getCurrencySql(year) {
  const currencySql = `select * from AyoCurrency where YEAR='${year}'`;
  return new Promise(async (resolve, reject) => {
    await mssql.query(currencySql, (err, currency2) => {
      resolve(currency2.recordset);
    });
  });
}
